mapper.update:
UPDATE aid_assistant_source_import
SET status = #{targetStatus},
    lease_owner = #{owner},
    lease_until = #{leaseUntil},
    fencing_token = fencing_token + 1,
    state_revision = state_revision + 1,
    update_by = #{operator},
    update_time = #{now}
WHERE id = #{id}
  AND state_revision = #{expectedStateRevision}
  AND status = #{expectedStatus}
  AND del_flag = '0'
  AND ((lease_owner IS NULL AND lease_until IS NULL) OR lease_until <= #{now})
